def pluck(arr):
    min_even = float('inf')
    min_index = -1
    for i, val in enumerate(arr):
        if val % 2 == 0:
            if val < min_even:
                min_even = val
                min_index = i
    if min_index == -1:
        return []
    return [min_even, min_index]

def search(lst):
