def encrypt(s):
    res = ""
    for char in s:
        if 'a' <= char <= 'z':
            res += chr((ord(char) - ord('a') + 4) % 26 + ord('a'))
        elif 'A' <= char <= 'Z':
            res += chr((ord(char) - ord('A') + 4) % 26 + ord('A'))
        else:
